worker="import datetime,hashlib,json,os,pathlib,shutil,subprocess,sys,tarfile,tomllib,urllib.parse,urllib.request\nroot=pathlib.Path.cwd();out=root/'output/session-20261029/native-rust-standalone';out.mkdir(parents=True,exist_ok=False)\nversion='1.93.0';target='aarch64-apple-darwin';prefix=root/'build-deps'/('rust-'+version+'-'+target)\nif shutil.disk_usage(root).free<6*1024**3:raise SystemExit('Need6GiB free for task-scoped Rust and WebTransport')\nif prefix.exists():raise SystemExit('Standalone toolchain prefix already exists; inspect instead of overwriting')\nprefix.mkdir(parents=True)\ndownloads=out/'downloads';downloads.mkdir()\n\ndef download(url,destination,maximum):\n parsed=urllib.parse.urlparse(url)\n if parsed.scheme!='https' or parsed.hostname!='static.rust-lang.org':raise SystemExit('Only official Rust HTTPS distribution URLs are allowed')\n digest=hashlib.sha256();size=0\n with urllib.request.urlopen(url,timeout=45) as response,destination.open('xb') as output:\n  if urllib.parse.urlparse(response.url).hostname!='static.rust-lang.org':raise SystemExit('Unexpected distribution redirect')\n  while True:\n   block=response.read(1024*1024)\n   if not block:break\n   size+=len(block)\n   if size>maximum:raise SystemExit('Distribution download exceeded explicit size bound')\n   output.write(block);digest.update(block)\n return {'url':url,'sha256':digest.hexdigest(),'bytes':size}\nmanifest_path=downloads/('channel-rust-'+version+'.toml')\nmanifest_receipt=download('https://static.rust-lang.org/dist/channel-rust-'+version+'.toml',manifest_path,4*1024**2)\nmanifest=tomllib.loads(manifest_path.read_text())\nif not manifest['pkg']['rustc']['version'].startswith(version+' '):raise SystemExit('Official release manifest version differs')\nreceipts=[]\nfor component in ('rustc','rust-std','cargo'):\n entry=manifest['pkg'][component]['target'][target]\n if not entry.get('available'):raise SystemExit('Official Apple component is unavailable: '+component)\n name=pathlib.PurePosixPath(urllib.parse.urlparse(entry['xz_url']).path).name\n archive=downloads/name;receipt=download(entry['xz_url'],archive,300*1024**2)\n if receipt['sha256']!=entry['xz_hash']:raise SystemExit('Official release component checksum mismatch: '+component)\n extraction=out/('extract-'+component);extraction.mkdir()\n with tarfile.open(archive,'r:xz') as tar:\n  members=tar.getmembers()\n  if len(members)>60000:raise SystemExit('Rust component contains too many archive entries')\n  tops={pathlib.PurePosixPath(member.name).parts[0] for member in members if member.name}\n  if len(tops)!=1:raise SystemExit('Rust component must have one archive root')\n  tar.extractall(extraction,filter='data')\n component_root=extraction/next(iter(tops));installer=component_root/'install.sh'\n if not installer.is_file():raise SystemExit('Official component installer missing')\n p=subprocess.run(['sh',str(installer),'--prefix='+str(prefix),'--disable-ldconfig'],cwd=component_root,text=True,capture_output=True,timeout=90)\n (out/(component+'-install.log')).write_text(p.stdout+p.stderr)\n if p.returncode:raise SystemExit('Task-scoped component installation failed: '+component)\n receipt.update({'component':component,'official_manifest_hash_matched':True,'prefix':str(prefix.relative_to(root))})\n receipts.append(receipt);(out/'components.json').write_text(json.dumps(receipts,indent=2)+'\\n')\nenv=os.environ.copy();env.pop('RUSTUP_TOOLCHAIN',None)\nenv.update({'PATH':str(prefix/'bin')+os.pathsep+env.get('PATH',''),'RUSTC':str(prefix/'bin/rustc'),'CARGO_HOME':str(root/'build-deps/cargo-home-1.93.0'),'CARGO_BUILD_JOBS':'2','CARGO_TARGET_DIR':str(root/'build-deps/webtransport/target'),'CARGO_INCREMENTAL':'0'})\nversions={name:subprocess.check_output([str(prefix/'bin'/name),'--version'],text=True,env=env,timeout=30).strip() for name in ('rustc','cargo')}\nif not versions['rustc'].startswith('rustc '+version+' '):raise SystemExit('Installed compiler version differs')\n(out/'toolchain.json').write_text(json.dumps({'manifest':manifest_receipt,'components':receipts,'versions':versions,'prefix':str(prefix.relative_to(root)),'global_defaults_changed':False,'existing_V8_unchanged':True},indent=2)+'\\n')\nrows=[]\ndef measured(name,command,duration):\n metric=out/name\n p=subprocess.run(['python3','tools/monitor_process.py','--duration',str(duration),'--settle','0','--output',str(metric.relative_to(root)),'--',*command],text=True,capture_output=True,env=env,timeout=duration+30)\n (out/(name+'-collector.log')).write_text(p.stdout+p.stderr)\n report=json.loads(metric.with_suffix('.json').read_text());passed=report.get('natural_exit_code')==0 and not report.get('collector_error') and not report.get('ended_by_monitor')\n rows.append({'stage':name,'passed':passed,'exit_code':report.get('natural_exit_code'),'interval_cpu_samples':report.get('interval_cpu_samples'),'rss_peak_mib':report.get('rss_peak_mb')});(out/'stages.json').write_text(json.dumps(rows,indent=2)+'\\n');return passed\nfetched=measured('cargo-fetch',[str(prefix/'bin/cargo'),'fetch','--locked','--target',target,'--manifest-path','src/net/webtransport-native/Cargo.toml'],300)\nbuilt=fetched and measured('webtransport-build',['python3','src/net/webtransport-native/build_component.py','--target',target,'--profile','release'],900)\nsummary={'finished_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'webtransport_built':built,'stages':rows,'toolchain_prefix':str(prefix.relative_to(root)),'versions':versions,'browser_transport_verified':False,'scope':'Official prebuilt Rust restored only inside project; locked native WebTransport dependency build, not browser network acceptance. Existing V8 reused unchanged.'}\np=root/'build-deps/webtransport/macos/manifest.json'\nif built:summary['backend_manifest']={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'value':json.loads(p.read_text())}\n(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\\n');print(json.dumps(summary));sys.exit(not built)\n"
